HDR = 'import Janus.Contracts.ErrorfSat\nimport Janus.Contracts.ErrorfMem\nimport Janus.Contracts.ErrorfRealCode\nimport Janus.Contracts.RelocArm64\n\n/-!\n# Loop lemmas of the real-format `fmt.errorf` stub (arm64)\n\nGENERATED by `scripts/dev/errorf/gen_loops.py` from the templates in that script (one decimal loop per number,\none byte-copy loop per segment). Each lemma is stated for the stub `ErrorfRealCode.code` at its own\nloop head and exit and takes the rest of the run as a continuation `htail`.\n-/\n\nnamespace Janus.Contracts.ErrorfRealLoops\n\nopen Janus Janus.Arm64 Janus.GoABI Janus.Tactic Janus.Contracts Janus.Contracts.Toy Janus.Contracts.LiveSat Janus.Spec\n  Janus.Spec.Errorf Janus.Contracts.ErrorfMem\nopen Janus.Contracts.RelocArm64 (codeProg)\nopen Janus.Contracts.ErrorfRealCode (code E0)\n\nset_option maxRecDepth 100000\n\n'
DIG = "theorem dig_@N@ (s : State) (h30 : (s.regs 30).toNat < 2 ^ 48) (h30' : (s.regs 30).toNat % 4 = 0) :\n    ∀ (t : Nat) (R : Nat → W64) (m : Memory) (F : Flags) (endp : Nat),\n      t < 2 ^ 64 → R 11 = BitVec.ofNat 64 t → R 13 = BitVec.ofNat 64 endp → R 15 = 10#64 → R 30 = s.regs 30 →\n      (natBytes t).length ≤ endp → endp < 2 ^ 48 →\n      m.accessible (endp - (natBytes t).length) (natBytes t).length true = true →\n      ∀ Q : State → Prop,\n        (∀ c : W64, ReachesRet (codeProg E0 code) (s.regs 30)\n          { s with regs := setReg (setReg (setReg (setReg R 11 0#64) 13 (BitVec.ofNat 64 (endp - (natBytes t).length))) 14 0#64) 16 c,\n                   flags := F, mem := putBytes m (endp - (natBytes t).length) (natBytes t), pc := @X@#64 } Q) →\n        ReachesRet (codeProg E0 code) (s.regs 30) { s with regs := R, flags := F, mem := m, pc := @H@#64 } Q := by\n  intro t\n  induction t using Nat.strongRecOn with\n  | _ t ih =>\n  intro R m F endp ht h11 h13 h15 h30R hle hend hacc Q htail\n  have hpos := natBytes_length_pos t\n  have h1e : 1 ≤ endp := by omega\n  janus_run [h11, h13, h15, h30R] until [@H@, @X@]\n  · -- exit: t < 10\n    have ht10 : t < 10 := by omega\n    have hq : t / 10 = 0 := by omega\n    have := htail (BitVec.ofNat 64 t - BitVec.ofNat 64 (t / 10) * 10#64 + 48#64)\n    rw [natBytes_lt ht10] at this\n    simp only [List.length_singleton, putBytes_cons, putBytes_nil, hq] at this ⊢\n    refine Eq.mpr (congrArg (fun st => ReachesRet (codeProg E0 code) (s.regs 30) st Q) ?_) this\n    congr 1\n    · have hsub : BitVec.ofNat 64 endp - 1#64 = BitVec.ofNat 64 (endp - 1) := by\n        apply BitVec.eq_of_toNat_eq\n        simp only [BitVec.toNat_sub, BitVec.toNat_ofNat]\n        omega\n      rw [hsub]\n    · have : (0#64 * 10#64).toNat = 0 := by decide\n      rw [this]\n      congr 1\n      omega\n  · have h10 : 10 ≤ t := by omega\n    have hq : t / 10 < t := by omega\n    have hlen : (natBytes t).length = (natBytes (t / 10)).length + 1 := by\n      rw [natBytes_ge h10]; simp\n    have hpos' := natBytes_length_pos (t / 10)\n    have hdig : (18446744073709551616 - (BitVec.ofNat 64 (t / 10) * 10#64).toNat + t + 48) % 18446744073709551616\n        = 48 + t % 10 := by\n      have : (BitVec.ofNat 64 (t / 10) * 10#64).toNat = t / 10 * 10 := by\n        simp only [BitVec.toNat_mul, BitVec.toNat_ofNat]\n        rw [Nat.mod_eq_of_lt (by omega : t / 10 < 2 ^ 64), Nat.mod_eq_of_lt (by omega : t / 10 * 10 < 2 ^ 64)]\n      rw [this]; omega\n    have hsub : BitVec.ofNat 64 endp - 1#64 = BitVec.ofNat 64 (endp - 1) := by\n      apply BitVec.eq_of_toNat_eq\n      simp only [BitVec.toNat_sub, BitVec.toNat_ofNat]\n      omega\n    rw [hdig, hsub]\n    refine ih (t / 10) hq _ _ _ (endp - 1) (by omega) (by simp [setReg]) (by simp [setReg]) (by simp [setReg, h15]) (by simp [setReg, h30R])\n      (by omega) (by omega) ?_ Q ?_\n    · simp only [Janus.Arm64.Memory.accessible_writeLE]\n      exact Memory.accessible_mono _ hacc (by omega) (by omega)\n    · intro c\n      have := htail c\n      refine Eq.mpr (congrArg (fun st => ReachesRet (codeProg E0 code) (s.regs 30) st Q) ?_) this\n      congr 1\n      · have e : endp - 1 - (natBytes (t / 10)).length = endp - (natBytes t).length := by omega\n        rw [e]\n        funext i\n        simp only [setReg]\n        split <;> simp_all\n      · rw [putBytes_writeLE_comm _ _ _ _ _ (Or.inr (by omega))]\n        have e : endp - 1 - (natBytes (t / 10)).length = endp - (natBytes t).length := by omega\n        rw [e, natBytes_ge h10, putBytes_snoc]\n        simp only [List.length_append, List.length_singleton]\n        have e2 : endp - ((natBytes (t / 10)).length + 1) + (natBytes (t / 10)).length = endp - 1 := by omega\n        rw [e2]\n"
CPY = "theorem cpy_@N@ (s : State) (h30 : (s.regs 30).toNat < 2 ^ 48) (h30' : (s.regs 30).toNat % 4 = 0) :\n    ∀ (cnt : Nat) (R : Nat → W64) (m : Memory) (F : Flags) (src dst : Nat),\n      cnt < 2 ^ 48 → R 12 = BitVec.ofNat 64 cnt → R 10 = BitVec.ofNat 64 src → R 11 = BitVec.ofNat 64 dst →\n      R 30 = s.regs 30 → src + cnt ≤ 2 ^ 48 → dst + cnt ≤ 2 ^ 48 →\n      (src + cnt ≤ dst ∨ dst + cnt ≤ src) →\n      (cnt = 0 ∨ m.accessible src cnt false = true) → (cnt = 0 ∨ m.accessible dst cnt true = true) →\n      ∀ Q : State → Prop,\n        (∀ c : W64, ReachesRet (codeProg E0 code) (s.regs 30)\n          { s with regs := setReg (setReg (setReg (setReg R 10 (BitVec.ofNat 64 (src + cnt))) 11 (BitVec.ofNat 64 (dst + cnt))) 12 0#64) 16 c,\n                   flags := F, mem := putBytes m dst (strBytes m src cnt), pc := @X@#64 } Q) →\n        ReachesRet (codeProg E0 code) (s.regs 30) { s with regs := R, flags := F, mem := m, pc := @H@#64 } Q := by\n  intro cnt\n  induction cnt with\n  | zero =>\n    intro R m F src dst hc h12 h10 h11 h30R hs hd hdis hsa hda Q htail\n    janus_run [h12, h10, h11, h30R] until [@H@, @X@]\n    have := htail (R 16)\n    refine Eq.mpr (congrArg (fun st => ReachesRet (codeProg E0 code) (s.regs 30) st Q) ?_) this\n    congr 1\n    · funext i\n      simp only [setReg, h10, h11, h12, Nat.add_zero]\n      by_cases e16 : i = 16 <;> by_cases e12 : i = 12 <;> by_cases e11 : i = 11 <;> by_cases e10 : i = 10 <;> simp_all\n  | succ cnt ih =>\n    intro R m F src dst hc h12 h10 h11 h30R hs hd hdis hsa hda Q htail\n    have hsa' : m.accessible src (cnt + 1) false = true := by\n      rcases hsa with h | h; omega; exact h\n    have hda' : m.accessible dst (cnt + 1) true = true := by\n      rcases hda with h | h; omega; exact h\n    janus_run [h12, h10, h11, h30R] until [@H@, @X@]\n    have hb : m.readLE src 1 % 18446744073709551616 = (m.bytes src).toNat := by\n      rw [Memory.readLE_one]; exact Nat.mod_eq_of_lt (by have := (m.bytes src).isLt; omega)\n    rw [hb]\n    have hdis' : src + 1 + cnt ≤ dst + 1 ∨ dst + 1 + cnt ≤ src + 1 := by omega\n    refine ih _ _ _ (src + 1) (dst + 1) (by omega) ?_ ?_ ?_ (by simp [setReg, h30R]) (by omega) (by omega) hdis' ?_ ?_ Q ?_\n    · simp [setReg]; apply BitVec.eq_of_toNat_eq; simp [BitVec.toNat_sub, BitVec.toNat_ofNat]; omega\n    · simp [setReg]; apply BitVec.eq_of_toNat_eq; simp [BitVec.toNat_add, BitVec.toNat_ofNat, h10]\n    · simp [setReg]; apply BitVec.eq_of_toNat_eq; simp [BitVec.toNat_add, BitVec.toNat_ofNat, h11]\n    · by_cases hz : cnt = 0\n      · exact Or.inl hz\n      · exact Or.inr (by simp only [Janus.Arm64.Memory.accessible_writeLE]; exact Memory.accessible_mono _ hsa' (by omega) (by omega))\n    · by_cases hz : cnt = 0\n      · exact Or.inl hz\n      · exact Or.inr (by simp only [Janus.Arm64.Memory.accessible_writeLE]; exact Memory.accessible_mono _ hda' (by omega) (by omega))\n    · intro c\n      have := htail c\n      refine Eq.mpr (congrArg (fun st => ReachesRet (codeProg E0 code) (s.regs 30) st Q) ?_) this\n      congr 1\n      · funext i\n        simp only [setReg, show dst + 1 + cnt = dst + (cnt + 1) by omega, show src + 1 + cnt = src + (cnt + 1) by omega]\n        by_cases e16 : i = 16 <;> by_cases e12 : i = 12 <;> by_cases e11 : i = 11 <;> by_cases e10 : i = 10 <;> simp_all\n      · have e : strBytes (m.writeLE dst 1 (m.bytes src).toNat) (src + 1) cnt = strBytes m (src + 1) cnt := by\n          have := strBytes_putBytes_out m dst [(m.bytes src).toNat] (src + 1) cnt (by simp; omega)\n          simpa [putBytes_cons] using this\n        rw [e, strBytes_succ, putBytes_cons]\n"
